int factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

void swap(int a, int b) {
    int t = a; a = b; b = t;
}
int x = 10, y = 20;
swap(x, y);

class Base {
public:
    virtual void show() { cout << "Base"; }
};
class Derived : public Base {
public:
    void show() override { cout << "Derived"; }
};
Base *b = new Derived();
b->show();

